from typing import Callable, List, Sequence

def diagonal_out_of_enumeration(programs: Sequence[Callable[[int], int]]) -> Callable[[int], int]:
    """Return total d with d(n) != programs[n](n) for all n (Cantor/Turing diagonal)."""
    def d(n: int) -> int:
        return programs[n](n) + 1 if n < len(programs) else 0
    return d

def run() -> None:
    programs: List[Callable[[int], int]] = [lambda n: 0, lambda n: n, lambda n: n*n, lambda n: 2*n+1]
    d = diagonal_out_of_enumeration(programs)
    for i, p in enumerate(programs):
        assert d(i) != p(i)
        print(f"d({i})={d(i)}  program_{i}({i})={p(i)}  differ=True")
    print("d escapes every listed program -> no countable list captures all functions.")

if __name__ == "__main__":
    run()

from typing import Dict, List, Sequence

Degree = int

def turing_jump(level: Degree) -> Degree:
    """Abstract jump: strictly increases the degree (level < J(level))."""
    return level + 1

def jump_tower(base: Degree, height: int) -> List[Degree]:
    tower = [base]
    for _ in range(height):
        tower.append(turing_jump(tower[-1]))
    return tower

def is_strictly_increasing(seq: Sequence[Degree]) -> bool:
    return all(a < b for a, b in zip(seq, seq[1:]))

def run() -> None:
    tower = jump_tower(0, 6)
    print("tower:", tower)
    print("strictly increasing:", is_strictly_increasing(tower))
    print("all distinct       :", len(set(tower)) == len(tower))
    emb: Dict[int, Degree] = {n: tower[n] for n in range(len(tower))}
    faithful = all((n < m) == (emb[n] < emb[m]) for n in emb for m in emb)
    print("order embedding of (N,<):", faithful)

if __name__ == "__main__":
    run()

from typing import Set

Degree = int

def turing_jump(level: Degree) -> Degree:
    return level + 1

def relativize_with_computable_oracle(base_class: Set[int], oracle: int) -> Set[int]:
    """Rec({g}) = Partrec when g is already computable; a non-computable oracle adds power."""
    return set(base_class) if oracle in base_class else base_class | {oracle}

def run() -> None:
    partrec: Set[int] = {0, 1, 2, 3}
    print("computable oracle useless:", relativize_with_computable_oracle(partrec, 2) == partrec)
    print("halting oracle adds power:", relativize_with_computable_oracle(partrec, 99) > partrec)
    for a in range(4):
        ja, jja = turing_jump(a), turing_jump(turing_jump(a))
        print(f"A={a}: J(A)={ja} J(J(A))={jja} strictly greater={ja < jja}")

if __name__ == "__main__":
    run()

